		num += sourceUnit.SpecialEffects.OfType<MindlessData>().Sum((MindlessData s) => s.CurrentCostIncreasedRate);
		double num2 = num - attributeValue_Final;
		if (num2 < 0.2)
		{
			num2 = 0.2;
		}
		double num3 = GetGaugeCost(skill);
		TacticRageCostChangeData tacticRageCostChangeData = sourceUnit.SpecialEffects.OfType<TacticRageCostChangeData>().FirstOrDefault();
		if (tacticRageCostChangeData != null)
		{
			num3 = tacticRageCostChangeData.Cost;
		}
		if (sourceUnit.GetUnitType() == UnitClass.Killer)
		{
			ThousandKnivesExtremeDamageEnhancementData thousandKnivesExtremeDamageEnhancementData = sourceUnit.SpecialEffects.OfType<ThousandKnivesExtremeDamageEnhancementData>().FirstOrDefault();
