private static double CalculateFinalPercentagedValue(double percentage, double value)
	{
		if (percentage >= 0.0)
		{
			if (value >= 0.0)
			{
				return value * percentage;
			}
			return (0.0 - value) * percentage;
		}
		if (value >= 0.0)
		{
			return value * percentage;
		}
		return 0.0 - value * percentage;
	}

public static double GetAttributeValue(this List<AttributeModifier> attributes, AttributeType type, AttributeRetrievalLevel retrievalLevel)
	{
		List<AttributeModifier> list = attributes.Where((AttributeModifier a) => (!type.IsResistanceAttribute()) ? (a.AttributeType == type) : (a.AttributeType == type || a.AttributeType == AttributeType.Allresistances)).ToList();
		List<AttributeModifier> source = list.Where((AttributeModifier a) => a.AttributeModifierType == AttributeModifierType.Normal).ToList();
		double num = source.Where((AttributeModifier a) => a.ModificationType == ModificationType.Addition).Sum((AttributeModifier a) => a.Value);
		double percentage = source.Where((AttributeModifier a) => a.ModificationType == ModificationType.Multiplication).Sum((AttributeModifier a) => a.Value);
		double num2 = CalculateFinalPercentagedValue(percentage, num);
		num += num2;
		if (source.Any((AttributeModifier a) => a.ModificationType == ModificationType.Replacement))
		{
			num = attributes.Last((AttributeModifier a) => a.ModificationType == ModificationType.Replacement).Value;
		}
		num = type.ValidateAttributeValue(num);
		if (retrievalLevel == AttributeRetrievalLevel.Naked)
		{
			return num;
		}
		List<AttributeModifier> source2 = list.Where((AttributeModifier a) => a.AttributeModifierType == AttributeModifierType.Gear || a.AttributeModifierType == AttributeModifierType.Embeded || a.AttributeModifierType == AttributeModifierType.Growth).ToList();
		double num3 = source2.Where((AttributeModifier a) => a.ModificationType == ModificationType.Addition).Sum((AttributeModifier a) => a.Value);
		double percentage2 = source2.Where((AttributeModifier a) => a.ModificationType == ModificationType.Multiplication).Sum((AttributeModifier a) => a.Value);
		double num4 = CalculateFinalPercentagedValue(percentage2, num3 + num);
		double value = num3 + num + num4;
		value = type.ValidateAttributeValue(value);
		if (source2.Any((AttributeModifier a) => a.ModificationType == ModificationType.Replacement))
		{
			value = source2.Last((AttributeModifier a) => a.ModificationType == ModificationType.Replacement).Value;
		}
		List<AttributeModifier> source3 = list.Where((AttributeModifier a) => a.AttributeModifierType == AttributeModifierType.SetBonus).ToList();
		double num5 = source3.Where((AttributeModifier a) => a.ModificationType == ModificationType.Addition).Sum((AttributeModifier a) => a.Value);
		double percentage3 = source3.Where((AttributeModifier a) => a.ModificationType == ModificationType.Multiplication).Sum((AttributeModifier a) => a.Value);
		double num6 = CalculateFinalPercentagedValue(percentage3, value + num5);
		double value2 = value + num5 + num6;
		value2 = type.ValidateAttributeValue(value2);
		if (retrievalLevel == AttributeRetrievalLevel.Gear)
		{
			return value2;
		}
		return CalculateSkillLevelAttributeFinalValue(type, list, value2);
	}

private static double CalculateSkillLevelAttributeFinalValue(AttributeType type, List<AttributeModifier> filteredAttributes, double bonusLevelResult)
	{
		List<AttributeModifier> source = filteredAttributes.Where((AttributeModifier a) => a.AttributeModifierType == AttributeModifierType.Skill).ToList();
		double num = source.Where((AttributeModifier a) => a.ModificationType == ModificationType.Addition).Sum((AttributeModifier a) => a.Value);
		double percentage = source.Where((AttributeModifier a) => a.ModificationType == ModificationType.Multiplication).Sum((AttributeModifier a) => a.Value);
		double num2 = CalculateFinalPercentagedValue(percentage, bonusLevelResult + num);
		double value = bonusLevelResult + num + num2;
		if (source.Any((AttributeModifier a) => a.ModificationType == ModificationType.Replacement))
		{
			value = source.Last((AttributeModifier a) => a.ModificationType == ModificationType.Replacement).Value;
		}
		return type.ValidateAttributeValue(value);
	}

public static double ValidateAttributeValue(this AttributeType type, double value)
	{
		switch (type)
		{
		case AttributeType.PhysicalResistance:
		case AttributeType.FireResistanceResistance:
		case AttributeType.ShadowResistance:
		case AttributeType.IceResistance:
		case AttributeType.PoisonResistance:
		case AttributeType.DivineResistance:
		case AttributeType.LightningResistance:
			return value;
		case AttributeType.ReceivedHealEffectivenessChangeRate:
		case AttributeType.DealFireDamageEffectivenessChangeRate:
		case AttributeType.DealPhysicalDamageEffectivenessChangeRate:
		case AttributeType.DealIceDamageEffectivenessChangeRate:
		case AttributeType.DealShadowDamageEffectivenessChangeRate:
		case AttributeType.DealPoisonDamageEffectivenessChangeRate:
		case AttributeType.DealDivineDamageEffectivenessChangeRate:
		case AttributeType.DealLightningDamageEffectivenessChangeRate:
			if (value <= -1.0)
			{
				return -1.0;
			}
			return value;
		case AttributeType.DamageReduction:
		case AttributeType.SkillRageEfficiencyRate:
			return value;
		case AttributeType.CritDamage:
			if (value < 1.0)
			{
				return 1.0;
			}
			return value;
		default:
			if (value < 0.0)
			{
				return 0.0;
			}
			return value;
		}
	}

