		if (dealer.SpecialEffects.OfType<OffensiveDamageIgnoreByAttackerData>().Any() && (dealer.GetUnitClassStyle() == UnitClassStyle.PhysicalKiller || dealer.GetUnitClassStyle() == UnitClassStyle.SpellKiller))
		{
