public static double RetrieveLeveledValue(this Dictionary<AttributeRetrievalLevel, Dictionary<AttributeType, Dictionary<ModificationType, double?>>> values, AttributeRetrievalLevel level, AttributeType type)
	{
		if (values.ContainsKey(AttributeRetrievalLevel.Naked))
		{
			bool flag = type.IsResistanceAttribute();
			double num = values[AttributeRetrievalLevel.Naked][type][ModificationType.Addition].GetValueOrDefault();
			double num2 = values[AttributeRetrievalLevel.Naked][type][ModificationType.Multiplication].GetValueOrDefault();
			if (flag)
			{
				num += values[AttributeRetrievalLevel.Naked][AttributeType.Allresistances][ModificationType.Addition].GetValueOrDefault();
				num2 += values[AttributeRetrievalLevel.Naked][AttributeType.Allresistances][ModificationType.Multiplication].GetValueOrDefault();
			}
			double num3 = CalculateFinalPercentagedValue(num2, num);
			double value = num + num3;
			value = type.ValidateAttributeValue(value);
			if (values[AttributeRetrievalLevel.Naked][type][ModificationType.Replacement].HasValue)
			{
				value = values[AttributeRetrievalLevel.Naked][type][ModificationType.Replacement].Value;
			}
			if (flag && values[AttributeRetrievalLevel.Naked][AttributeType.Allresistances][ModificationType.Replacement].HasValue)
			{
				value = values[AttributeRetrievalLevel.Naked][AttributeType.Allresistances][ModificationType.Replacement].Value;
			}
			if (level == AttributeRetrievalLevel.Naked)
			{
				return value;
			}
			double num4 = values[AttributeRetrievalLevel.Gear][type][ModificationType.Addition].GetValueOrDefault();
			double num5 = values[AttributeRetrievalLevel.Gear][type][ModificationType.Multiplication].GetValueOrDefault();
			if (flag)
			{
				num4 += values[AttributeRetrievalLevel.Gear][AttributeType.Allresistances][ModificationType.Addition].GetValueOrDefault();
				num5 += values[AttributeRetrievalLevel.Gear][AttributeType.Allresistances][ModificationType.Multiplication].GetValueOrDefault();
			}
			double num6 = CalculateFinalPercentagedValue(num5, num4 + value);
			double value2 = num4 + num6 + value;
			value2 = type.ValidateAttributeValue(value2);
			if (values[AttributeRetrievalLevel.Gear][type][ModificationType.Replacement].HasValue)
			{
				value2 = values[AttributeRetrievalLevel.Gear][type][ModificationType.Replacement].Value;
			}
			if (flag && values[AttributeRetrievalLevel.Gear][AttributeType.Allresistances][ModificationType.Replacement].HasValue)
			{
				value2 = values[AttributeRetrievalLevel.Gear][AttributeType.Allresistances][ModificationType.Replacement].Value;
			}
			double num7 = values[AttributeRetrievalLevel.Bonus][type][ModificationType.Addition].GetValueOrDefault();
			double num8 = values[AttributeRetrievalLevel.Bonus][type][ModificationType.Multiplication].GetValueOrDefault();
			if (flag)
			{
				num7 += values[AttributeRetrievalLevel.Bonus][AttributeType.Allresistances][ModificationType.Addition].GetValueOrDefault();
				num8 += values[AttributeRetrievalLevel.Bonus][AttributeType.Allresistances][ModificationType.Multiplication].GetValueOrDefault();
			}
			double num9 = CalculateFinalPercentagedValue(num8, num7 + value2);
			double value3 = num9 + num7 + value2;
			value3 = type.ValidateAttributeValue(value3);
			if (values[AttributeRetrievalLevel.Bonus][AttributeType.Allresistances][ModificationType.Replacement].HasValue)
			{
				value3 = values[AttributeRetrievalLevel.Bonus][AttributeType.Allresistances][ModificationType.Replacement].Value;
			}
			return value3;
		}
		return 0.0;
	}

