				list.Add(new AttributeDisplayValue
				{
					AttributeType = item2,
					Value = value,
					ModificationType = ModificationType.Addition
				});
			}
		}
		var originalBenefits = (from ef in profile.GetEquipments().GetSetBenefits().SelectMany((SetItemResult b) => b.MajorEffects)
			select new
			{
				Effect = ef,
				AsString = JsonUtility.ToJson(ef)
			}).ToList();
		var updatedBenefits = (from ef in profile.GetEquipments().ReplaceItem(item).GetSetBenefits()
				.SelectMany((SetItemResult b) => b.MajorEffects)
			select new
			{
				Effect = ef,
				AsString = JsonUtility.ToJson(ef)
			}).ToList();
		var source = originalBenefits.Where(o => updatedBenefits.All(u => u.AsString != o.AsString)).ToList();
		var source2 = updatedBenefits.Where(u => originalBenefits.All(o => o.AsString != u.AsString)).ToList();
		EquipedItemResult equipedItemResult = new EquipedItemResult();
		equipedItemResult.AddedSpecialEffects = source2.Select(a => a.Effect).ToList();
		equipedItemResult.Changes = list;
		equipedItemResult.LostSpecialEffects = source.Select(a => a.Effect).ToList();
