					where r.ReductionTypes.Any((OutputType t) => t == type)
					select r).ToList();
				if (source.Any())
				{
					num3 += (double)source.Sum((DamageReductionEffect r) => r.ReductionRate);
				}
			}
			initDefensiveRating *= 1.0 - num3;
			if ((unit is AdventurerBattleUnit || unit is PetBattleUnit) && initDefensiveRating <= 0.1)
			{
				return 0.1;
			}
			if (unit is EnemyBattleUnit && initDefensiveRating <= 0.001)
			{
				return 0.001;
			}
			return initDefensiveRating;
		}
		return 1.0;
	}

