	{
		if (evtType != AdventureEventType.BattleEncounterPlayerGaugeReleased && evtType != AdventureEventType.BattleEncounterEnemyGaugeReleased)
		{
			yield break;
		}
		BattleGaugeUpdateEvent change = evtData as BattleGaugeUpdateEvent;
		DarkRageData data = specialEffectData as DarkRageData;
		if (change == null || data == null || !(change.ChangeAmount > 0.0) || ((!effectCarrier.IsPlayer || evtType != AdventureEventType.BattleEncounterEnemyGaugeReleased) && (effectCarrier.IsPlayer || evtType != AdventureEventType.BattleEncounterPlayerGaugeReleased)))
		{
			yield break;
		}
		string effectSourceCode = "darkknightdarkrage";
		double changeAmount = (0.0 - change.ChangeAmount) * data.ChargeRate;
		List<AttributeModificationEffect> currentEffects = (from ef in effectCarrier.BattleEffects.OfType<AttributeModificationEffect>()
			where ef.EffectSourceIdentityCode == effectSourceCode
			select ef).ToList();
		List<AttributeModifier> existingModifiers = ((!currentEffects.Any()) ? data.ChargeAttributeTypes.Select((AttributeType a) => new AttributeModifier
		{
			AttributeType = a,
			ModificationType = ModificationType.Addition,
			Value = changeAmount,
			AttributeModifierType = AttributeModifierType.Skill,
			Key = string.Empty
		}).ToList() : (from ef in currentEffects.SelectMany((AttributeModificationEffect ef) => ef.GetAdditionalModifiers(effectCarrier, effectCarrier.CurrentEncounter))
			group ef by ef.AttributeType into ef
			select new AttributeModifier
			{
				AttributeType = ef.Key,
				ModificationType = ModificationType.Addition,
				Value = ef.Sum((AttributeModifier f) => f.Value) + changeAmount,
				AttributeModifierType = AttributeModifierType.Skill,
				Key = string.Empty
			}).ToList());
		IEnumerator enumerator = effectCarrier.ApplySkillEffect(AttributeModificationEffect.CreateArbitraryPostiveAttributeModificationEffect(effectCarrier, existingModifiers, effectSourceCode, 1, null, null, canbeImmune: false, canbeDispersed: false)).GetEnumerator();
		try
		{
			while (enumerator.MoveNext())
			{
				yield return enumerator.Current;
			}
		}
		finally
		{
			IDisposable disposable2;
			IDisposable disposable = (disposable2 = enumerator as IDisposable);
			if (disposable2 != null)
			{
				disposable.Dispose();
			}
		}
	}

