				if (disposable2 != null)
				{
					disposable.Dispose();
				}
			}
			data.CoolingDownCounter -= data.CoolingDownSecondsAfterRebirth;
		}
		if (data.HaveRevived || data.CoolingDownCounter < data.CoolingDownSeconds)
		{
			yield break;
		}
		IEnumerator enumerator2 = effectCarrier.ApplySkillEffect(new InversedKillEffect(effectCarrier, data.DamageRate, data.DamageType, data.ChannelingSeconds)).GetEnumerator();
		try
