		}
		List<double> list = new List<double>();
		list.Add(GetHealRate(skill.Skill));
		return new StableHealDefinition(list, new TargetDefinition(TargetCandidateType.FriendlyAlive, CandidateOrderringMetric.HealthPointPercentage, OrderingType.Asc, 1), OutputType.Heal, skill);
