public override IEnumerable PostDamageProcess(ReleaseableDamage damage, AdventureUnitSkill skill)
	{
		IBattleUnit caster = skill.SourceUnit;
		bool canTaunt = !skill.GetActiveTalents().OfType<TauntDamageEnhancementTalent>().Any();
		int tauntTime = 4;
		if (skill.GetActiveTalents().OfType<TauntTimeEnhancementTalent>().Any())
		{
			tauntTime = TauntTimeEnhancementTalent.TauntTime;
		}
		List<TauntDebuffTalent> tauntDebuff = skill.GetActiveTalents().OfType<TauntDebuffTalent>().ToList();
		foreach (BattleDamage damageBattleDamage in damage.BattleDamages)
		{
			IBattleUnit target = damageBattleDamage.Target;
			if (target.BattleEffects.OfType<TauntEffect>().Any())
			{
				foreach (TauntDebuffTalent tauntDebuffTalent in tauntDebuff)
				{
					IEnumerator enumerator3 = target.ApplySkillEffect(AttributeModificationEffect.CreateArbitraryNegativeAttributeModificationEffect(skill.SourceUnit, new List<AttributeModifier>
					{
						new AttributeModifier
						{
							AttributeType = TauntDebuffTalent.Type,
							ModificationType = ModificationType.Multiplication,
							Value = 0.0 - TauntDebuffTalent.ReductionRate,
							Key = string.Empty,
							AttributeModifierType = AttributeModifierType.Skill
						}
					}, "tauntdebuff", 3, 5f, null, canbeImmune: true, canbeDispersed: true)).GetEnumerator();
					try
					{
						while (enumerator3.MoveNext())
						{
							yield return enumerator3.Current;
						}
					}
					finally
					{
						IDisposable disposable2;
						IDisposable disposable = (disposable2 = enumerator3 as IDisposable);
						if (disposable2 != null)
						{
							disposable.Dispose();
						}
					}
				}
			}
			if (target.Status != BattleUnitStatus.Active || !damageBattleDamage.Damages.Any((DamageComponent d) => !d.IsMissed) || !canTaunt)
			{
				continue;
			}
			bool cannotBeResisted = false;
			PaladinStarTauntEnhanceData star = skill.SourceUnit.SpecialEffects.OfType<PaladinStarTauntEnhanceData>().FirstOrDefault();
			if (star != null && (double)UnityEngine.Random.value <= star.Chance)
			{
				cannotBeResisted = true;
			}
			IEnumerator enumerator4 = target.ApplySkillEffect(new TauntEffect(caster, target, skill, tauntTime, !cannotBeResisted)).GetEnumerator();
			try
			{
				while (enumerator4.MoveNext())
				{
					yield return enumerator4.Current;
				}
			}
			finally
			{
				IDisposable disposable2;
				IDisposable disposable3 = (disposable2 = enumerator4 as IDisposable);
				if (disposable2 != null)
				{
					disposable3.Dispose();
				}
			}
		}
	}

