		{
			source = wearer.CurrentEncounter.PlayerUnits;
		}
		int num = source.Count((IBattleUnit t) => t.BattleEffects.OfType<TauntEffect>().Any((TauntEffect tt) => tt.Caster == wearer));
		if (num > 0)
