				Key = string.Empty,
				AttributeModifierType = AttributeModifierType.Skill
			});
		}
		if (Caster.GetUnitType() == UnitClass.Paladin)
		{
			PaladinDecayEnhancementData paladinDecayEnhancementData = Caster.SpecialEffects.OfType<PaladinDecayEnhancementData>().FirstOrDefault();
			if (paladinDecayEnhancementData != null)
			{
				double attributeValue_Final = Caster.GetAttributeValue_Final(AttributeType.Resilience, AttributeRetrievalLevel.Skill);
				if (attributeValue_Final > 0.0)
				{
					list.Add(new AttributeModifier
